// Engine demo for "your friend pauses YOU" (There's a catch EP08, 13 Nov 2026; engine/shared/pause.js `world: false`
// + `look: "frozen"`): in a plain living room Reaper waves and lobs an apple at 0.9 s; Wizard's power freezes ONLY
// Reaper 1.0-2.6 s, mid-wave and grey-cool, while Wizard keeps moving, the apple keeps flying and the dust keeps
// drifting in full colour; at 2.6 s the colour floods back out of Reaper from the same point and he finishes the wave.
//   node storyboards/env/make-pause-frozen-demo.mjs -> pause-frozen-demo.json
//   node engine/render.mjs storyboards/env/pause-frozen-demo.json --stills 0.9,1.05,1.4,1.8,2.2,2.65,3.0 --draft
import { clip, write } from "../lib/clip.mjs";

const c = clip({ faces: "strong", lines: { sub: false, blink: false } }), { A } = c, END = 3.6;
const P0 = 1.0, P1 = 2.6, REA = [-0.7, -0.6], WIZ = [0.7, -0.6];
const HIT = [-0.62, 0.55, -0.45];   // where the power lands: Reaper's chest, on Wizard's side
// Reaper: holds the apple, waves it up and lobs it toward the front right; the wave runs through the pause's start
// (held mid-way, finished after it), then his arm comes down
A(0, "rea", "grab", { prop: "apple", hand: "R", dur: 0 });
A(0.45, "rea", "arm", { side: "R", pose: "wave", dur: 0.8 });
// the lob: a let-go at 0.85, then aimed a frame later (docs/STORYBOARD.md "Pause time": the knock starts from where the
// let-go left it; a throw on the let-go's frame would start from the prop's own spot); lands at 1.95 and rolls on
A(0.85, "rea", "release", { prop: "apple", dur: 0 });
c.knock(0.9, "apple", { to: [0.3, 0.06, 0.5], in: 1.05, spin: [2, 0.5, 3] });
A(P1 + 0.3, "rea", "arm", { side: "R", pose: "rest", dur: 0.5 });
// Wizard keeps moving through it: looks at the frozen Reaper, follows the apple down, points, steps toward it
A(0.3, "wiz", "look", { to: [-0.6, 0.0], dur: 0.3 });
A(P0 + 0.15, "wiz", "expr", { expr: "eager", set: { curve: 0.5 }, dur: 0.2 });
A(P0 + 0.3, "wiz", "look", { to: [-0.3, 0.3], dur: 0.35 });
A(P0 + 0.6, "wiz", "look", { to: [-0.2, -0.45], dur: 0.4 });
A(P0 + 0.7, "wiz", "arm", { side: "L", pose: "point", dur: 0.5 });
A(P0 + 1.35, "wiz", "arm", { side: "L", pose: "rest", dur: 0.5 });
A(P0 + 1.1, "wiz", "move", { to: [0.62, -0.35], dur: 0.6, steps: 1.2 });
A(P1 + 0.1, "rea", "expr", { expr: "annoyed", dur: 0.2 });
const beats = c.beats([["all", 0, { pos: [0, 1.1, 5.0], look: [0, 0.68, -0.5], fov: 44 }]], END);
write(import.meta.url, {
  id: "pause-frozen-demo", title: "Pause YOU (engine demo)", idea: "Engine demo, not a clip: one actor paused, the world runs on (shared/pause.js)",
  fps: 30, look: "anime-pro", castLook: "sheet", profile: "short", loop: false, captionStyle: "kinetic", cleanStart: true,
  motion: { feet: 2, overlap: true, timing: true, solve: true }, rig: { hand: 2, eyes: 2, hold: 2 }, physics: true, animeTiming: true,
  set: { type: "livingroom", seed: 5, focus: false, aperture: 0, lighting: 2, hatch: { boil: 0.25 }, cel: { at: 0.25 } },
  music: false, sound: { sfx: 0.7, ambience: 0.4, guard: true },
  hook: { show: ["rea", "wiz"], hint: 0, what: "engine demo" },
  pause: [{ from: P0, to: P1, keep: ["wiz"], world: false, look: "frozen", hit: HIT }],
  cast: [
    { id: "rea", character: "notyet/reaper-noscythe", at: REA, face: 30, expr: "deadpan", follow: 0.3, seed: 3.3 },
    { id: "wiz", character: "notyet/wizard-nostaff", at: WIZ, face: -30, expr: "happy", follow: 0.3, seed: 2.1 },
  ],
  props: [
    { id: "apple", kind: "apple", x: -0.45, y: 0.42, z: -0.42, scale: 1.25 },
    { id: "dust", kind: "dustmotes", x: 0, y: 0.1, z: -0.4, n: 70, box: [2.6, 1.7, 2.4], seed: 71 },
  ],
  captions: c.captions, beats, visible: c.visible,
  notes: "Generated by storyboards/env/make-pause-frozen-demo.mjs (engine demo).",
});
